class Color { 
 public:

  // Components.
  float r; /**< value of red chanel   */
  float g; /**< value of green chanel */
  float b; /**< value of blue chanel  */
  float a; /**< value of alpha chanel */

  // constants
  static const Color White;
  static const Color Black;

  /**
   * Constructor.
   * Initialize from component values.
   * By default, alpha is initialized to 1.
   * \param r Value of the red chanel.
   * \param g Value of the green chanel.
   * \param b Value of the blue chanel.
   * \param a Value of the alpha chanel.
   */
  Color( float r = 0, float g = 0, float b = 0, float a = 1.0 )
      : r( r ), g( g ), b( b ), a( a ) { }

  /**
   * Constructor.
   * Initialize from array of 8-bit component values (RGB only).
   * \param arr Array containing component values.
   */
  Color( const unsigned char* arr );

  // Addition. Alpha is ignored.
  inline Color operator+( const Color& rhs ) const {
    return Color( r + rhs.r, g + rhs.g, b + rhs.b, a + rhs.a);
  }

  inline Color& operator+=( const Color& rhs ) {
    r += rhs.r; g += rhs.g; b += rhs.b; a += rhs.a;
    return *this;
  }

  // Vector multiplication. Alpha is ignored.
  inline Color operator*( const Color& rhs ) const {
    return Color( r * rhs.r, g * rhs.g, b * rhs.b, a * rhs.a);
  }

  inline Color& operator*=( const Color& rhs ) {
    r *= rhs.r; g *= rhs.g; b *= rhs.b; a *= rhs.a;
    return *this;
  }

  // Scalar multiplication.
  inline Color operator*( float s ) const {
    return Color( r * s, g * s, b * s, a * s );
  }

  inline Color& operator*=( float s ) {
    r *= s; g *= s; b *= s; a *= s;
    return *this;
  }

  // comparison
  inline bool operator==( const Color& rhs ) const {
    return r == rhs.r && g == rhs.g && b == rhs.b && a == rhs.a;
  }

  inline bool operator!=( const Color& rhs ) const {
    return !operator==( rhs );
  }

  /** 
   * Construct a Color object from a hexadecimal (8-bit per
   * component) ASCII string. 
   * Since hexademical strings are typically not used to encode 
   * alpha values, the alpha is set to 1 (opaque) by default.  
   * This method also accepts the string "none", in which case 
   * it returns a color value with alpha zero (transparent).
   * \return Color constructed from the input hex encoding.
   */
  static Color fromHex( const char* s );

  /** 
   * Returns a hexadecimal string #rrggbb encoding this color.
   * \return the hexadecimal encoding of the color.
   */
  std::string toHex( ) const;


}; // class Color


// Commutable scalar multiplication.
inline Color operator*( float s, const Color& c ) {
  return c * s;
}

// Prints components.
std::ostream& operator<<( std::ostream& os, const Color& c );

} // namespace CGL

#endif

#ifndef CGL_COMPLEX_H
#define CGL_COMPLEX_H

#include "vector2D.h"

namespace CGL {

/**
* Represents complex numbers as 2D vectors of their real and
* imaginary components.
*/
class Complex : public Vector2D {
 public:

  /**
   * Constructor.
   * Initializes to 0.
   */
  Complex( ) : Vector2D( 0.0, 0.0 ) { }

  /**
   * Constructor.
   * Initializes to a+bi.
   */
  Complex( double a, double b ) : Vector2D( a, b ) { }

  /**
   * Constructor.
   * Initializes to a+bi from vector v = (a,b)
   */
  Complex( const Vector2D& v ) : Vector2D( v ) { }

  /**
   * Compute the complex conjugate.
   */
  inline Complex conj( ) const {
    return Complex( x, -y );
  }

  /**
   * Compute the inverse.
   */
  inline Complex inv( ) const {
    double r = 1.0/norm2();
    return Complex( r*x, -r*y );
  }

  /**
   * Return argument.
   */
  inline double arg( ) const {
    return atan2( y, x );
  }

  /**
   * Complex exponentiation.
   */
  inline Complex exponential( ) const {
    return exp( x ) * Complex( cos( y ), sin( y ));
  }

  // Complex multiply by z
  inline void operator*=( const Complex& z ) {
    double a = x;
    double b = y;
    double c = z.x;
    double d = z.y;
    x = a*c-b*d;
    y = a*d+b*c;
  }

  // complex divide by z
  void operator/=( const Complex& z ) {
    *this *= z.inv();
  }

}; // class Complex

// returns the real part of z
double Re( const Complex& z );

// returns the imaginary part of z
double Im( const Complex& z );

// binary Complex multiplication
inline Complex operator*( const Complex& z1, const Complex& z2 ) {
    Complex z = z1;
    z *= z2;
    return z;
}

// complex division
inline Complex operator/( const Complex& z1, const Complex& z2 ) {
    Complex z = z1;
    z /= z2;
    return z;
}

// prints components
std::ostream& operator<<( std::ostream& os, const Complex& z );

} // namespace CGL

#endif // CGL_COMPLEX_H

#ifndef CGL_MATRIX3X3_H
#define CGL_MATRIX3X3_H

#include <iosfwd>

#include "vector3D.h"

namespace CGL {

/**
 * Defines a 3x3 matrix.
 * 3x3 matrices are extremely useful in computer graphics.
 */
class Matrix3x3 {

  public:

  // The default constructor.
  Matrix3x3(void) { }

  // Constructor for row major form data.
  // Transposes to the internal column major form.
  // REQUIRES: data should be of size 9 for a 3 by 3 matrix..
  Matrix3x3(double * data)
  {
    for( int i = 0; i < 3; i++ )
    for( int j = 0; j < 3; j++ )
    {
	  // Transpostion happens within the () query.
	  (*this)(i,j) = data[i*3 + j];
    }

  }



  /**
   * Sets all elements to val.
   */
  void zero(double val = 0.0 );

  /**
   * Returns the determinant of A.
   */
  double det( void ) const;

  /**
   * Returns the Frobenius norm of A.
   */
  double norm( void ) const;

  /**
   * Returns the 3x3 identity matrix.
   */
  static Matrix3x3 identity( void );

  /**
   * Returns a matrix representing the (left) cross product with u.
   */
  static Matrix3x3 crossProduct( const Vector3D& u );

  /**
   * Returns the ith column.
   */
        Vector3D& column( int i );
  const Vector3D& column( int i ) const;

  /**
   * Returns the transpose of A.
   */
  Matrix3x3 T( void ) const;

  /**
   * Returns the inverse of A.
   */
  Matrix3x3 inv( void ) const;

  // accesses element (i,j) of A using 0-based indexing
        double& operator()( int i, int j );
  const double& operator()( int i, int j ) const;

  // accesses the ith column of A
        Vector3D& operator[]( int i );
  const Vector3D& operator[]( int i ) const;

  // increments by B
  void operator+=( const Matrix3x3& B );

  // returns -A
  Matrix3x3 operator-( void ) const;

  // returns A-B
  Matrix3x3 operator-( const Matrix3x3& B ) const;

  // returns c*A
  Matrix3x3 operator*( double c ) const;

  // returns A*B
  Matrix3x3 operator*( const Matrix3x3& B ) const;

  // returns A*x
  Vector3D operator*( const Vector3D& x ) const;

  // divides each element by x
  void operator/=( double x );

  protected:

  // column vectors
  Vector3D entries[3];

}; // class Matrix3x3

// returns the outer product of u and v
Matrix3x3 outer( const Vector3D& u, const Vector3D& v );

// returns c*A
Matrix3x3 operator*( double c, const Matrix3x3& A );

// prints entries
std::ostream& operator<<( std::ostream& os, const Matrix3x3& A );

} // namespace CGL

#endif // CGL_MATRIX3X3_H

#ifndef CGL_MATRIX4X4_H
#define CGL_MATRIX4X4_H

#include <iosfwd>

#include "vector4D.h"

namespace CGL {

/**
 * Defines a 4x4 matrix.
 * 4x4 matrices are also extremely useful in computer graphics.
 * Written by Bryce Summers on 9/10/2015.
 * Adapted from the Matrix3x3 class.
 *
 * EXTEND_ME : It might be nice to add some combined operations
 *             such as multiplying then adding,
 *             etc to increase arithmetic intensity.
 * I have taken the liberty of removing cross product functionality form 4D Matrices and Vectors.
 */
class Matrix4x4 {

  public:


  // The default constructor.
  Matrix4x4(void) { }

  // Constructor for row major form data.
  // Transposes to the internal column major form.
  // REQUIRES: data should be of size 16.
  Matrix4x4(double * data)
  {
    for( int i = 0; i < 4; i++ )
    for( int j = 0; j < 4; j++ )
    {
	  // Transpostion happens within the () query.
	  (*this)(i,j) = data[i*4 + j];
    }

  }


  /**
   * Sets all elements to val.
   */
  void zero(double val = 0.0);

  /**
   * Returns the determinant of A.
   */
  double det( void ) const;

  /**
   * Returns the Frobenius norm of A.
   */
  double norm( void ) const;

  /**
   * Returns a fresh 4x4 identity matrix.
   */
  static Matrix4x4 identity( void );

  // No Cross products for 4 by 4 matrix.

  /**
   * Returns the ith column.
   */
        Vector4D& column( int i );
  const Vector4D& column( int i ) const;

  /**
   * Returns the transpose of A.
   */
  Matrix4x4 T( void ) const;

  /**
   * Returns the inverse of A.
   */
  Matrix4x4 inv( void ) const;

  // accesses element (i,j) of A using 0-based indexing
  // where (i, j) is (row, column).
        double& operator()( int i, int j );
  const double& operator()( int i, int j ) const;

  // accesses the ith column of A
        Vector4D& operator[]( int i );
  const Vector4D& operator[]( int i ) const;

  // increments by B
  void operator+=( const Matrix4x4& B );

  // returns -A
  Matrix4x4 operator-( void ) const;

  // returns A-B
  Matrix4x4 operator+( const Matrix4x4& B ) const;

  // returns A-B
  Matrix4x4 operator-( const Matrix4x4& B ) const;

  // returns c*A
  Matrix4x4 operator*( double c ) const;

  // returns A*B
  Matrix4x4 operator*( const Matrix4x4& B ) const;

  // returns A*x
  Vector4D operator*( const Vector4D& x ) const;

  // divides each element by x
  void operator/=( double x );

  protected:

  // 4 by 4 matrices are represented by an array of 4 column vectors.
  Vector4D entries[4];

}; // class Matrix3x3

// returns the outer product of u and v.
Matrix4x4 outer( const Vector4D& u, const Vector4D& v );

// returns c*A
Matrix4x4 operator*( double c, const Matrix4x4& A );

// prints entries
std::ostream& operator<<( std::ostream& os, const Matrix4x4& A );

} // namespace CGL

#endif // CGL_MATRIX4X4_H

